#include <stdlib.h>
#include <limits.h>

typedef struct {
    int x;
    int y;
} Point;

typedef struct {
    int x;
    int y;
} Pair;

typedef struct PairNode {
    int y1;
    int y2;
    int x;
    struct PairNode* next;
} PairNode;

int cmpPoint(const void* a, const void* b) {
    Point* p1 = (Point*)a;
    Point* p2 = (Point*)b;
    if (p1->x != p2->x) return p1->x - p2->x;
    return p1->y - p2->y;
}

int cmpInt(const void* a, const void* b) {
    return (*(int*)a) - (*(int*)b);
}

int minAreaRect(int** points, int pointsSize, int* pointsColSize){
    // Step 1: Sort points by x then y
    Point* pts = (Point*)malloc(pointsSize * sizeof(Point));
    for (int i = 0; i < pointsSize; i++) {
        pts[i].x = points[i][0];
        pts[i].y = points[i][1];
    }
    qsort(pts, pointsSize, sizeof(Point), cmpPoint);

    // Step 2: Group points by x coordinate
    // We'll store the y coordinates for each distinct x in an array
    // We can store them in a dynamic array of arrays
    int maxXGroups = pointsSize; // worst case all distinct x
    int* xVals = (int*)malloc(maxXGroups * sizeof(int));
    int** yVals = (int**)malloc(maxXGroups * sizeof(int*));
    int* yCounts = (int*)malloc(maxXGroups * sizeof(int));
    int groupCount = 0;

    int currentX = pts[0].x;
    yVals[0] = (int*)malloc(pointsSize * sizeof(int));
    yCounts[0] = 0;
    xVals[0] = currentX;
    for (int i = 0; i < pointsSize; i++) {
        if (pts[i].x != currentX) {
            groupCount++;
            currentX = pts[i].x;
            xVals[groupCount] = currentX;
            yVals[groupCount] = (int*)malloc(pointsSize * sizeof(int));
            yCounts[groupCount] = 0;
        }
        yVals[groupCount][yCounts[groupCount]++] = pts[i].y;
    }
    groupCount++;

    // Step 3: For each x group, sort the y values
    for (int i = 0; i < groupCount; i++) {
        qsort(yVals[i], yCounts[i], sizeof(int), cmpInt);
    }

    // Step 4: Use a hash map to store pairs of y coordinates and the last x where they appeared
    // Since C doesn't have built-in hash maps, we use a simple approach:
    // We'll store pairs as keys in a hash table with chaining.
    // The key is a pair of y1,y2 (y1 < y2), the value is the last x coordinate where this pair appeared.

    // Define hash table size
    #define HASH_SIZE 10007

    typedef struct HashEntry {
        int y1;
        int y2;
        int lastX;
        struct HashEntry* next;
    } HashEntry;

    HashEntry* hashTable[HASH_SIZE];
    for (int i = 0; i < HASH_SIZE; i++) hashTable[i] = NULL;

    // Hash function for pair (y1,y2)
    unsigned int hashFunc(int y1, int y2) {
        // A simple hash combining y1 and y2
        unsigned int hash = (unsigned int)(y1 * 40009 + y2);
        return hash % HASH_SIZE;
    }

    int findLastX(int y1, int y2) {
        unsigned int h = hashFunc(y1, y2);
        HashEntry* cur = hashTable[h];
        while (cur) {
            if (cur->y1 == y1 && cur->y2 == y2) return cur->lastX;
            cur = cur->next;
        }
        return -1;
    }

    void updateLastX(int y1, int y2, int x) {
        unsigned int h = hashFunc(y1, y2);
        HashEntry* cur = hashTable[h];
        while (cur) {
            if (cur->y1 == y1 && cur->y2 == y2) {
                cur->lastX = x;
                return;
            }
            cur = cur->next;
        }
        // Not found, insert new
        HashEntry* newEntry = (HashEntry*)malloc(sizeof(HashEntry));
        newEntry->y1 = y1;
        newEntry->y2 = y2;
        newEntry->lastX = x;
        newEntry->next = hashTable[h];
        hashTable[h] = newEntry;
    }

    int minArea = INT_MAX;
    // Step 5: For each x group, consider all pairs of y coordinates
    for (int i = 0; i < groupCount; i++) {
        int* ys = yVals[i];
        int count = yCounts[i];
        int x = xVals[i];
        for (int j = 0; j < count; j++) {
            for (int k = j+1; k < count; k++) {
                int y1 = ys[j];
                int y2 = ys[k];
                int lastX = findLastX(y1, y2);
                if (lastX != -1) {
                    int area = (x - lastX) * (y2 - y1);
                    if (area < minArea) minArea = area;
                }
                updateLastX(y1, y2, x);
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < groupCount; i++) {
        free(yVals[i]);
    }
    free(yVals);
    free(yCounts);
    free(xVals);
    free(pts);

    // Free hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        HashEntry* cur = hashTable[i];
        while (cur) {
            HashEntry* tmp = cur;
            cur = cur->next;
            free(tmp);
        }
    }

    if (minArea == INT_MAX) return 0;
    return minArea;
}

